package net.battlespades.ugc;

import java.io.IOException;
import java.nio.file.Path;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import net.battlespades.entities.EntityRegistry;
import net.battlespades.match.Announcements;
import net.battlespades.physics.PlayerPhysics.Vector;
import net.battlespades.player.*;
import net.battlespades.protocol.*;
import net.battlespades.replication.*;
import net.battlespades.runtime.OwnerLoop;
import net.battlespades.scene.*;
import net.battlespades.session.*;
import net.battlespades.transport.enet.Delivery;
import net.battlespades.world.*;

/** Concrete isolated creator scene over the real loader, lives, physics, replication and editor owners. */
public final class CreatorScene implements JoinScene {
    private final Thread owner=Thread.currentThread();private final SceneConfig config;private final ScenePackets.Environment environment;private final PreparedMap.Bound prepared;private final LifeRuntime.Clock clock;private final OwnerLoop loop;private final Executor writer;private final Consumer<Throwable> failure;private final UgcWorkspace workspace;private final List<String> prefabs;private final List<GamePacket> source;private final LifeRuntime lives;private final UgcEditor editor;private final UgcConstruction construction;private final StandardSpawns spawns;private final SelectionChanges selections;private final PaletteRelay palette;
    private final Map<Integer,JoinSession> connections=new HashMap<>();private final Map<PlayerLife,PlayerSnapshot> snapshots=new IdentityHashMap<>();private final EntityRegistry entities=new EntityRegistry();private ApplicationHost host;private InfantrySimulation infantry;private ReplicationService replication;private Integer fog;private byte[] preview;private CompletableFuture<Void> previewTask=CompletableFuture.completedFuture(null);private CompletionStage<Void> stopped;private boolean closing;private int frame;
    public CreatorScene(SceneConfig base,MapMetadata metadata,PreparedMap.Bound prepared,UgcWorkspace.Opened opened,List<String> prefabs,List<Path> roots,LifeRuntime.Clock clock,OwnerLoop loop,Executor writer,ExecutorService modelWorker,Consumer<Throwable> failure)throws IOException{
        this.prepared=Objects.requireNonNull(prepared);this.config=UgcPresentation.config(base,opened.project());this.environment=metadata.environment();if(prepared.world().sourceCrc()!=environment.sourceCrc())throw new IllegalArgumentException("Creator metadata/world mismatch");this.clock=Objects.requireNonNull(clock);this.loop=Objects.requireNonNull(loop);this.writer=Objects.requireNonNull(writer);this.failure=Objects.requireNonNull(failure);this.prefabs=List.copyOf(prefabs);if(prefabs.isEmpty())throw new IllegalArgumentException("Creator requires installed palette constructs");workspace=new UgcWorkspace(opened.files());preview=workspace.preview().orElse(null);source=UgcWire.source(opened.source());fog=UgcCatalog.FOG.get(opened.project().skybox());
        lives=new LifeRuntime(prepared.world(),config.rules(),"ugc",clock,new LifeRuntime.Policy(){
            public AdmissionPolicy.Context admissionContext(int id){return AdmissionPolicy.Context.ordinary(List.of());}public void prepareSpawn(PlayerLife p){}public Vector spawnPoint(PlayerLife p){return spawns.spawnPlain(p);}public Optional<Vector> spawnOrientation(PlayerLife p){return Optional.empty();}public boolean canRespawn(PlayerLife p){return !closing;}public double respawnDelay(PlayerLife p){return 0;}public double walletScale(){return 1;}public int teamColor(PlayerLife p){return config.team1().color();}public int score(PlayerLife p){return 0;}public boolean opponents(PlayerLife a,PlayerLife b){return false;}public int deathType(PlayerLife a,PlayerLife b,int type){return type;}public Optional<LifeRuntime.DamageModifier> damageModifier(){return Optional.of((p,n,s,t)->0);}public boolean combatScoringActive(){return false;}
        },new LifeRuntime.Effects(){
            public void beforeSpawn(PlayerLife p){}public void spawned(PlayerLife p){}public void died(PlayerLife p,PlayerLife k,int a,int b,boolean enemy){}public void damaged(LifeRuntime.DamageEvidence d){}public void healed(LifeRuntime.HealingEvidence d){}public void beforeDeath(LifeRuntime.DeathEvidence d){}public void transitionCredited(PlayerLife a,PlayerLife b,int type){}public void forget(PlayerLife p){construction.forget(p);selections.forget(p);palette.forget(p);snapshots.remove(p);}public void respawnFailed(PlayerLife p,RuntimeException error){failure.accept(error);}
        },new LifeRuntime.Messages(){public void broadcast(GamePacket p){CreatorScene.this.broadcast(p,null);}public void owner(int id,GamePacket p){send(id,p);}public boolean inGame(int id){return host!=null&&host.inGame(id);}},new LifeRuntime.Inputs(){public void reset(PlayerLife p){}public void receive(PlayerLife p,LiveClientInput input,int tick){if(ToolSelection.authorized(p,input.toolId(),true,false)){p.fire().tool(input.toolId(),true);if(input.toolId()==43)construction.brush(p,input);}else ToolSelection.ensureLegal(p,t->ToolSelection.authorized(p,t,true,false));}public void packet(PlayerLife p,GamePacket packet){construction.packet(p,packet);}public void forget(PlayerLife p){}});
        spawns=new StandardSpawns(prepared.spawns(),this,new SourceRandom(168),lives::players,clock::monotonic);
        editor=new UgcEditor(opened.project(),world(),opened.source(),entities,prefabs,"",loop,writer,UgcEditor.store(workspace),new UgcEditor.Ports(){public void broadcast(GamePacket p,Object exclude){CreatorScene.this.broadcast(p,exclude);}public void send(Object connection,GamePacket p){if(connection instanceof JoinSession s&&connections.containsValue(s))s.direct(p);}public void failure(Throwable e){failure.accept(e);}});
        construction=new UgcConstruction(world(),lives,editor.capacity(),roots,modelWorker,UgcConstruction.Settings.defaults(),clock::monotonic,new UgcConstruction.Ports(){public void broadcast(GamePacket p){CreatorScene.this.broadcast(p,null);}public void send(PlayerLife p,GamePacket packet){CreatorScene.this.send(p.id(),packet);}public void moved(PlayerLife p){if(replication!=null)replication.forgetPlayer(p.id());}public void built(PlayerLife p,Vector at){if(host!=null&&!closing)host.broadcastExcept(new AudioPackets.PlaySound(32,false,true,1,0,0,new Vector3f((float)at.x(),(float)at.y(),(float)at.z()),1),Delivery.UNRELIABLE,p.id());}public void sound(int id,Vector at){if(host!=null&&!closing)host.broadcast(new AudioPackets.PlaySound(id,false,true,1,0,0,new Vector3f((float)at.x(),(float)at.y(),(float)at.z()),1),Delivery.UNRELIABLE);}public void failure(Throwable e){failure.accept(e);}});
        selections=new SelectionChanges(lives,new SelectionChanges.Policy(){public ClassCatalog.Selection normalize(int id,List<Integer> tools,List<String> names,List<Integer> objects,int fallback){return editor.selection(new ClassCatalog.Selection(13,tools,names,objects));}public boolean selectable(int id){return id==13;}public boolean allows(PlayerLife p,ClassCatalog.Selection s){return p.team()==2&&s.classId()==13;}public boolean liveUgc(PlayerLife p,ClassCatalog.Selection s){return p.alive();}public void send(PlayerLife p,GamePacket packet){CreatorScene.this.send(p.id(),packet);}public void broadcast(GamePacket packet){CreatorScene.this.broadcast(packet,null);}public void failure(String label,RuntimeException e){failure.accept(e);}},clock::monotonic);
        palette=new PaletteRelay(lives,()->true,clock::monotonic,loop,(p,packet)->{if(host!=null)host.broadcastExcept(packet,Delivery.RELIABLE,p.id());});
    }
    private void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Creator scene outside owner");}
    public void attach(ApplicationHost host,ReplicationService.Settings replicationSettings){owned();if(this.host!=null||host.transitionScene()!=this)throw new IllegalStateException("Creator host attachment");this.host=host;replication=new ReplicationService(new ReplicationService.World(){public List<PlayerSnapshot> players(){var current=lives.players();snapshots.keySet().retainAll(current);return current.stream().map(p->snapshots.computeIfAbsent(p,key->new PlayerSnapshot(p,v->new PlayerSnapshot.Presentation(v.inventory().tool(),null,false,false,false,false,true,false)))).toList();}public List<? extends WorldUpdateLink> connections(){return host.snapshotLinks();}public List<EntityRecord> entities(){return List.of();}public List<WorldUpdate.TurretRow> turrets(){return List.of();}public void delivered(int count,long bytes){}},replicationSettings);lives.replication(replication);
        infantry=new InfantrySimulation(lives,new InfantrySimulation.Settings(environment.gravity(),false,false,8,false,8,24,false,6),new InfantrySimulation.Hooks(){public void lagHistory(PlayerLife p,int tick){}public void housekeeping(PlayerLife p){}public boolean burdened(PlayerLife p){return false;}public int pendingTerrainMutations(){return construction.pending();}public void report(PlayerLife p,String kind,boolean enforced){}public void disconnect(PlayerLife p,int reason){host.disconnectPlayer(p.id(),reason);}public void afterMove(PlayerLife p,double dt){}public void afterTick(PlayerLife p,double dt){}public void failed(PlayerLife p,RuntimeException e){failure.accept(e);}});
    }
    public LifeRuntime lives(){owned();return lives;}public UgcEditor editor(){owned();return editor;}public UgcConstruction construction(){owned();return construction;}public SceneConfig config(){return config;}
    private void broadcast(GamePacket packet,Object exclude){if(host==null||closing)return;for(var s:host.transitionSessions())if(s!=exclude)s.gameplay(packet,Delivery.RELIABLE);}
    private void send(int id,GamePacket packet){if(host!=null&&!closing)host.sendPlayer(id,packet);}
    @Override public MutableWorld world(){return prepared.world();}@Override public PlayerRoster roster(){return lives.roster();}@Override public boolean spectator(int id){return false;}
    @Override public InitialInfo initialInfo(int capability){owned();return UgcPresentation.initial(ScenePackets.initial(config,environment),editor.project());}
    @Override public InitialInfo initialInfo(JoinSession connection,int id,int capability){owned();if(closing)throw new IllegalStateException("Creator retiring");connections.put(id,connection);editor.connected(connection,"");return initialInfo(capability);}
    @Override public boolean shipsSourceMap(){return true;}@Override public Iterator<GamePacket> sourceMap(JoinSession connection,int id,int capability){return source.iterator();}
    @Override public StateData stateData(int id,int capability){owned();return UgcPresentation.state(ScenePackets.state(config,environment,ScenePackets.State.initial(config),id),prefabs,fog);}
    @Override public String skybox(){String sky=SceneConfig.validSkybox(editor.project().skybox());return sky==null?ScenePackets.skybox(config,environment):sky;}
    @Override public List<GamePacket> afterState(JoinSession connection,int id,int capability){return List.of(new SimplePackets.ForceTeamJoin(2,0));}
    @Override public Admission admit(int id,SimplePackets.NewPlayerConnection request,PlayerPackets.SetClassLoadout selection,int capability){owned();var pending=selection==null?new ClassCatalog.Selection(13,List.of(),List.of(),List.of()):new ClassCatalog.Selection(13,selection.loadout(),selection.prefabs(),selection.ugcTools());var chosen=editor.selection(pending);String name=net.battlespades.player.NameUnicode.strip(request.name().replace("\0",""));if(name.isEmpty())name="Builder";if(name.codePointCount(0,name.length())>31)name=name.substring(0,name.offsetByCodePoints(0,31));return lives.admit(id,new SimplePackets.NewPlayerConnection(2,13,0,request.local_language(),name),chosen,capability);}
    @Override public void beforeReplay(int id){lives.beforeReplay(id);}
    @Override public List<GamePacket> reveal(int id,int loop){owned();var packets=new ArrayList<GamePacket>(lives.reveal(id));editor.reveal(packets::add);packets.addAll(world().terrainHealth().reveal(id,loop,128));return List.copyOf(packets);}
    @Override public void input(int id,LiveClientInput input,int tick){lives.input(id,input,tick);}@Override public void position(int id,LivePositionReport report,int tick){lives.player(id).positionReports().receive(lives.player(id),report,clock.wall());}@Override public void roundTripMillis(int id,Double value){lives.roundTripMillis(id,value);}@Override public void actionLink(int id,ActionClock.Link value){lives.actionLink(id,value);}
    private JoinSession connection(int id){return Objects.requireNonNull(connections.get(id),"Creator socket missing");}
    private void save(int id){var socket=connection(id);editor.save(socket).whenComplete((ok,error)->{if(connections.get(id)==socket)send(id,Announcements.localised(error==null&&Boolean.TRUE.equals(ok)?"UGC_MAP_SAVE_SUCCESSFULLY":"UGC_MAP_SAVE_ERROR",List.of(),false,true));});}
    private void preview(int id,UgcPackets.Preview packet){var socket=connection(id);byte[] data=packet.data();if(!editor.isHost(socket)||!UgcWorkspace.validPreview(data)||!previewTask.isDone())return;previewTask=CompletableFuture.runAsync(()->{try{workspace.preview(data);}catch(IOException e){throw new CompletionException(e);}},writer).handleAsync((unused,error)->{if(error!=null){failure.accept(error);return null;}preview=data;editor.project().overhead(true);editor.checkpoint();broadcast(new UgcPackets.Preview(data),socket);return null;},loop);}
    private void skybox(int id,String value){var socket=connection(id);String sky=SceneConfig.validSkybox(value);if(!editor.isHost(socket)||sky==null)return;editor.project().skybox(sky);editor.checkpoint();broadcast(new SimplePackets.SkyboxData(sky),socket);Integer next=UgcCatalog.FOG.get(sky);if(next!=null){fog=next;broadcast(new UgcPackets.Fog(next),null);}}
    @Override public void packet(int id,GamePacket packet){owned();if(closing)return;var p=lives.player(id);var socket=connection(id);switch(packet){case LivePlacement v->{if(v.id()==97)editor.place(socket,p,new SimplePackets.PlaceUGC(v.loop(),v.x(),v.y(),v.z(),v.item(),v.placing()),frame);}case SimplePackets.PlaceUGC v->editor.place(socket,p,v,frame);case SimplePackets.SetUGCEditMode v->editor.targetMode(socket,v.mode());case UgcPackets.GroundColors v->editor.palette(socket,v);case SimplePackets.SkyboxData v->skybox(id,v.value());case UgcPackets.Preview v->preview(id,v);case SimplePackets.ReqestUGCEntities v->{if(host.inGame(id))editor.reveal(item->send(id,item));}case SimplePackets.UGCMessage v->{switch(v.message_id()){case 0->{if(editor.isHost(socket)){send(id,UgcWire.objectives(editor.project()));save(id);}}case 1->{if(editor.isHost(socket)){send(id,UgcWire.objectives(editor.project()));editor.checkpoint();}}case 4->{if(preview!=null)send(id,new UgcPackets.Preview(preview));}default->{}}}case PlayerPackets.SetClassLoadout v->{construction.forget(p);selections.loadout(p,v);lives.roster().appearance(p.create());}case SimplePackets.ChangeClass v->{if(v.class_id()==13)selections.change(p,13);}case SimplePackets.SetColor v->palette.set(p,v.value());case SimplePackets.ChangeTeam v->send(id,Announcements.localised("TEAM_SWITCH_NOT_ALLOWED",List.of(),false,false));default->lives.packet(id,packet);}}
    @Override public void disconnected(int id){owned();lives.disconnected(id);}@Override public void transitionDetach(int id){owned();lives.transitionDetach(id);}
    @Override public void connectionClosed(JoinSession connection,int id){owned();if(connections.get(id)==connection){connections.remove(id);editor.left(connection);}}
    public void frame(int tick){owned();frame=tick;}
    public void tick(int tick){owned();if(closing)return;frame=tick;lives.processRespawns();infantry.tick(tick);construction.tick(tick);editor.tick(clock.monotonic());replication.broadcast(tick,clock.monotonic());}
    /** Close the host first, then await this before closing the owner loop/world/workers. */
    public CompletionStage<Void> deactivate(){owned();if(stopped!=null)return stopped;closing=true;construction.close();palette.reset();stopped=previewTask.handleAsync((unused,error)->{if(error!=null)failure.accept(error);return null;},loop).thenComposeAsync(unused->editor.deactivate(),loop);return stopped;}
}
